package com.technova.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="pago") public class Pago { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_pago") private Long id; @Column(name="id_pedido") private Long pedidoId; @Column(name="fecha_pago") private LocalDateTime fechaPago; private String metodo; private BigDecimal monto; private String referencia,estado; public Pago(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getPedidoId(){return pedidoId;} public void setPedidoId(Long v){pedidoId=v;} public LocalDateTime getFechaPago(){return fechaPago;} public void setFechaPago(LocalDateTime v){fechaPago=v;} public String getMetodo(){return metodo;} public void setMetodo(String v){metodo=v;} public BigDecimal getMonto(){return monto;} public void setMonto(BigDecimal v){monto=v;} public String getReferencia(){return referencia;} public void setReferencia(String v){referencia=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
